      SUBROUTINE DSROTCCC     CALCULATES THE PARTIAL DERIVATIVES OF THE TRANSFER MATRIXC     ELEMENTS OF A KICK ELEMENT WITH RESPECT TO THE TILT (ROLL).CC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM20.CIN'CC     LOCAL VARIABLESC      REAL  CODS(6), CODT(6), DPUCC----------------------------------------------------------      IF (DCOV) THEN        DO 75 J = 1, 4   75   CODS(J) = COD(J)C        CODT(1) = - CODS(1)*SNR - CODS(3)*CSR        CODT(2) = - CODS(2)*SNR - CODS(4)*CSR        CODT(3) = CODS(1)*CSR - CODS(3)*SNR        CODT(4) = CODS(2)*CSR - CODS(4)*SNRC        DPU = DPARM*UNITI(13)        DO 455 J = 1, 4  455   CODV(J) = CODT(J)*DPU      ENDIF      RETURN      END